from datetime import datetime


class Classroom:
    def __init__(self, id):
        self.id = id
        self._courses = []

    @property
    def courses(self):
        return self._courses

    @courses.setter
    def courses(self, value):
        self._courses = value

    def add_course(self, course):
        if course not in self._courses:
            self._courses.append(course)

    def remove_course(self, course):
        if course in self._courses:
            self._courses.remove(course)

    def is_free_at(self, check_time):
        check_time_dt = self._parse_time(check_time)
        return all(not self._course_overlaps_time(course, check_time_dt) for course in self._courses)

    def check_course_conflict(self, new_course):
        new_start_time = self._parse_time(new_course['start_time'])
        new_end_time = self._parse_time(new_course['end_time'])
        return all(self._courses_do_not_overlap(course, new_start_time, new_end_time) for course in self._courses)

    def _parse_time(self, time_str):
        return datetime.strptime(time_str, '%H:%M')

    def _course_overlaps_time(self, course, time):
        start_time = self._parse_time(course['start_time'])
        end_time = self._parse_time(course['end_time'])
        return start_time <= time <= end_time

    def _courses_do_not_overlap(self, course, new_start_time, new_end_time):
        start_time = self._parse_time(course['start_time'])
        end_time = self._parse_time(course['end_time'])
        # Two intervals [s1, e1] and [s2, e2] do not overlap if e1 < s2 or e2 < s1
        return not (start_time <= new_end_time and end_time >= new_start_time)
